import{e as t,c as s,f as a,o as r}from"./DAzncX6o.js";const o={class:"min-h-screen bg-white pt-24 pb-16"},p={__name:"trust",setup(l){return t({title:"Trust & Safety | Erranders Barter",description:"Safety guidelines for buying, selling, and swapping on the Erranders network."}),(n,e)=>(r(),s("main",o,[...e[0]||(e[0]=[a('<div class="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8"><h1 class="text-4xl font-black text-slate-900 mb-6">Trust &amp; Safety Guidelines</h1><div class="prose prose-lg text-slate-600"><p>Your safety is our top priority. We&#39;ve built Erranders Barter to be the safest place to trade on campus.</p><h3 class="text-2xl font-bold text-slate-800 mt-8 mb-4">Always Use Escrow</h3><p>Never pay directly into a seller&#39;s personal bank account. Always use the built-in Escrow system to protect your money.</p><h3 class="text-2xl font-bold text-slate-800 mt-8 mb-4">Meet in Public Spaces</h3><p>If you are not using Erranders Logistics, ensure you meet the other party in a well-lit, public location on campus during daylight hours.</p><h3 class="text-2xl font-bold text-slate-800 mt-8 mb-4">Inspect Items Thoroughly</h3><p>Take your time to check the item before confirming delivery on the app. Once delivery is confirmed, funds are released and sales are final.</p></div></div>',1)])]))}};export{p as default};
